(function(){
  // Theme handling
  var root = document.documentElement;
  var toggleBtn = document.getElementById('theme-toggle');
  function applyIcon(){
    var isDark;
    var stored = null;
    try{ stored = localStorage.getItem('fc-theme'); }catch(e){}
    if(stored === 'light') isDark = false;
    else if(stored === 'dark') isDark = true;
    else isDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
    toggleBtn.textContent = isDark ? '☀️' : '🌙';
  }
  try{
    var stored = localStorage.getItem('fc-theme');
    if(stored === 'light' || stored === 'dark'){ root.setAttribute('data-theme', stored); }
  }catch(e){}
  applyIcon();

  toggleBtn.addEventListener('click', function(){
    var current = root.getAttribute('data-theme');
    var prefersDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
    var currentlyDark = current ? current === 'dark' : prefersDark;
    var next = currentlyDark ? 'light' : 'dark';
    root.setAttribute('data-theme', next);
    try{ localStorage.setItem('fc-theme', next); }catch(e){}
    applyIcon();
  });

  // Page routing
  var pages = document.querySelectorAll('.page');
  var navLinks = document.querySelectorAll('nav.links a');
  var allPageLinks = document.querySelectorAll('[data-page]');

  function showPage(name){
    if(!document.getElementById('page-' + name)) name = 'inicio';
    pages.forEach(function(p){ p.classList.toggle('active', p.id === 'page-' + name); });
    navLinks.forEach(function(a){ a.classList.toggle('active', a.getAttribute('data-page') === name); });
    window.scrollTo({top:0, behavior:'auto'});
  }

  allPageLinks.forEach(function(el){
    if(el.tagName === 'A' && el.hasAttribute('data-page')){
      el.addEventListener('click', function(e){
        e.preventDefault();
        var name = el.getAttribute('data-page');
        window.location.hash = name;
        showPage(name);
      });
    }
  });

  window.addEventListener('hashchange', function(){
    var name = window.location.hash.replace('#','') || 'inicio';
    showPage(name);
  });

  var initial = window.location.hash.replace('#','') || 'inicio';
  showPage(initial);

  // Pixel grid decorative animation (single orchestrated reveal)
  var grid = document.getElementById('pixel-grid');
  if(grid){
    var cells = 49;
    var order = Array.from({length:cells}, function(_,i){return i;});
    // shuffle for a more organic reveal
    for(var i = order.length -1; i>0; i--){
      var j = Math.floor(Math.random()*(i+1));
      var tmp = order[i]; order[i]=order[j]; order[j]=tmp;
    }
    var frag = document.createDocumentFragment();
    var spans = [];
    for(var k=0;k<cells;k++){
      var s = document.createElement('span');
      spans.push(s);
      frag.appendChild(s);
    }
    grid.appendChild(frag);
    order.forEach(function(cellIndex, i){
      spans[cellIndex].style.animationDelay = (i*18)+'ms';
    });
  }

  // Copy email
  var copyBtn = document.getElementById('copy-email-btn');
  var copyHint = document.getElementById('copy-hint');
  if(copyBtn){
    copyBtn.addEventListener('click', function(){
      var email = 'franciscocm1000@gmail.com';
      function done(ok){
        copyHint.textContent = ok ? 'Email copiado al portapapeles' : email;
      }
      try{
        navigator.clipboard.writeText(email).then(function(){done(true);}).catch(function(){done(false);});
      }catch(e){ done(false); }
    });
  }

  // CV download links
  var cvHref = "data:application/pdf;base64,";
  var heroCv = document.getElementById('hero-cv-link');
  var contactCv = document.getElementById('contact-cv-link');
  if(heroCv) heroCv.href = cvHref;
  if(contactCv) contactCv.href = cvHref;
})();